            - -c
            - /fluent-bit/etc/fluent-bit.conf
          env:
            - name: POD_NAME
              valueFrom:
                fieldRef:
                  fieldPath: metadata.name
            - name: POD_NAMESPACE
              valueFrom:
                fieldRef:
                  fieldPath: metadata.namespace
          securityContext:
            {{- toYaml .Values.fluentBit.securityContext | nindent 12 }}
          resources:
            {{- toYaml .Values.fluentBit.resources | nindent 12 }}
          volumeMounts:
            - name: fluent-bit-config
              mountPath: /fluent-bit/etc
              readOnly: true
            - name: {{ .Values.fluentBit.stateVolume.name }}
              mountPath: /var/fluent-bit/state
              readOnly: false
            - name: {{ .Values.logging.sharedVolume.name }}
              mountPath: {{ .Values.logging.path }}
              readOnly: true
            {{- with .Values.fluentBitExtraVolumeMounts }}
            {{- toYaml . | nindent 12 }}
            {{- end }}
---
# FILE: templates/hpa.yaml
{{- if .Values.autoscaling.enabled }}
apiVersion: autoscaling/v2
kind: HorizontalPodAutoscaler
metadata:
