      {{- end }}
      {{- if and .Values.topologySpreadConstraints.enabled .Values.topologySpreadConstraints.rules }}
      topologySpreadConstraints:
        {{- range .Values.topologySpreadConstraints.rules }}
        - maxSkew: {{ .maxSkew }}
          topologyKey: {{ .topologyKey }}
          whenUnsatisfiable: {{ .whenUnsatisfiable }}
          labelSelector:
            matchLabels:
              {{- include "app-with-fluent-bit.selectorLabels" $ | nindent 14 }}
            {{- with .labelSelector.matchLabels }}
              {{- toYaml . | nindent 14 }}
            {{- end }}
        {{- end }}
      {{- end }}
      {{- with .Values.affinity }}
      affinity:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      volumes:
        - name: {{ .Values.logging.sharedVolume.name }}
          emptyDir:
            {{- if .Values.logging.sharedVolume.medium }}
            medium: {{ .Values.logging.sharedVolume.medium | quote }}
            {{- end }}
            {{- if .Values.logging.sharedVolume.sizeLimit }}
            sizeLimit: {{ .Values.logging.sharedVolume.sizeLimit }}
            {{- end }}
        - name: {{ .Values.fluentBit.stateVolume.name }}
          emptyDir:
            {{- if .Values.fluentBit.stateVolume.sizeLimit }}
            sizeLimit: {{ .Values.fluentBit.stateVolume.sizeLimit }}
            {{- end }}
        - name: fluent-bit-config
          configMap:
            name: {{ include "app-with-fluent-bit.fullname" . }}-fluent-bit
      {{- with .Values.extraVolumes }}
        {{- toYaml . | nindent 8 }}
      {{- end }}
      containers:
        - name: app
          image: "{{ .Values.image.repository }}:{{ .Values.image.tag }}"
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          {{- with .Values.command }}
          command:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          {{- with .Values.args }}
          args:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          {{- if .Values.ports }}
          ports:
            {{- toYaml .Values.ports | nindent 12 }}
          {{- end }}
          {{- if .Values.probes.liveness.enabled }}
          livenessProbe:
            {{- toYaml .Values.probes.liveness | nindent 12 }}
          {{- end }}
          {{- if .Values.probes.readiness.enabled }}
          readinessProbe:
            {{- toYaml .Values.probes.readiness | nindent 12 }}
          {{- end }}
          {{- if .Values.probes.startup.enabled }}
          startupProbe:
            {{- toYaml .Values.probes.startup | nindent 12 }}
          {{- end }}
          env:
            - name: POD_NAME
              valueFrom:
                fieldRef:
                  fieldPath: metadata.name
            - name: POD_NAMESPACE
              valueFrom:
                fieldRef:
                  fieldPath: metadata.namespace
            {{- with .Values.env }}
            {{- toYaml . | nindent 12 }}
            {{- end }}
          securityContext:
            {{- toYaml .Values.containerSecurityContext | nindent 12 }}
          resources:
            {{- toYaml .Values.resources | nindent 12 }}
          volumeMounts:
            - name: {{ .Values.logging.sharedVolume.name }}
              mountPath: {{ .Values.logging.path }}
              readOnly: false
            {{- with .Values.extraVolumeMounts }}
            {{- toYaml . | nindent 12 }}
            {{- end }}
        - name: fluent-bit
          image: "{{ .Values.fluentBit.image.repository }}:{{ .Values.fluentBit.image.tag }}"
          imagePullPolicy: {{ .Values.fluentBit.image.pullPolicy }}
          args:
            - -c
            - /fluent-bit/etc/fluent-bit.conf
          env:
            - name: POD_NAME
              valueFrom:
                fieldRef:
                  fieldPath: metadata.name
            - name: POD_NAMESPACE
              valueFrom:
                fieldRef:
                  fieldPath: metadata.namespace
          securityContext:
            {{- toYaml .Values.fluentBit.securityContext | nindent 12 }}
          resources:
            {{- toYaml .Values.fluentBit.resources | nindent 12 }}
          volumeMounts:
            - name: fluent-bit-config
              mountPath: /fluent-bit/etc
              readOnly: true
            - name: {{ .Values.fluentBit.stateVolume.name }}
              mountPath: /var/fluent-bit/state
              readOnly: false
            - name: {{ .Values.logging.sharedVolume.name }}
              mountPath: {{ .Values.logging.path }}
              readOnly: true
            {{- with .Values.fluentBitExtraVolumeMounts }}
            {{- toYaml . | nindent 12 }}
            {{- end }}
---
# FILE: templates/hpa.yaml
{{- if .Values.autoscaling.enabled }}
apiVersion: autoscaling/v2
kind: HorizontalPodAutoscaler
metadata:
  name: {{ include "app-with-fluent-bit.fullname" . }}
  labels:
    {{- include "app-with-fluent-bit.labels" . | nindent 4 }}
spec:
  scaleTargetRef:
    apiVersion: apps/v1
    kind: Deployment
    name: {{ include "app-with-fluent-bit.fullname" . }}
  minReplicas: {{ .Values.autoscaling.minReplicas }}
  maxReplicas: {{ .Values.autoscaling.maxReplicas }}
  metrics:
    {{- if .Values.autoscaling.targetCPUUtilizationPercentage }}
    - type: Resource
      resource:
        name: cpu
        target:
          type: Utilization
          averageUtilization: {{ .Values.autoscaling.targetCPUUtilizationPercentage }}
    {{- end }}
    {{- if .Values.autoscaling.targetMemoryUtilizationPercentage }}
    - type: Resource
      resource:
        name: memory
        target:
          type: Utilization
          averageUtilization: {{ .Values.autoscaling.targetMemoryUtilizationPercentage }}
    {{- end }}
{{- end }}
---
# FILE: templates/pdb.yaml
{{- if and .Values.pdb.enabled (gt (int .Values.replicaCount) 1) }}
apiVersion: policy/v1
kind: PodDisruptionBudget
metadata:
  name: {{ include "app-with-fluent-bit.fullname" . }}
  labels:
    {{- include "app-with-fluent-bit.labels" . | nindent 4 }}
spec:
  selector:
    matchLabels:
      {{- include "app-with-fluent-bit.selectorLabels" . | nindent 6 }}
  {{- if .Values.pdb.maxUnavailable }}
  maxUnavailable: {{ .Values.pdb.maxUnavailable }}
  {{- end }}
{{- end }}
---
# FILE: templates/networkpolicy.yaml
{{- if .Values.networkPolicy.enabled }}
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: {{ include "app-with-fluent-bit.fullname" . }}
  labels:
    {{- include "app-with-fluent-bit.labels" . | nindent 4 }}
spec:
  podSelector:
    matchLabels:
      {{- include "app-with-fluent-bit.selectorLabels" . | nindent 6 }}
  policyTypes:
    - Ingress
    - Egress
  ingress:
    - from:
        {{- if .Values.networkPolicy.allowSameNamespace }}
        - podSelector: {}
        {{- end }}
        {{- range .Values.networkPolicy.allowNamespaces }}
        - namespaceSelector:
            matchExpressions:
              - key: {{ .key }}
                operator: {{ .operator }}
                values:
                  {{- toYaml .values | nindent 18 }}
        {{- end }}
      ports:
        - protocol: TCP
          port: {{ .Values.service.port }}
      {{- with .Values.networkPolicy.extraIngressRules }}
      {{- toYaml . | nindent 4 }}
      {{- end }}
  egress:
    {{- if .Values.networkPolicy.egress.allowDNS }}
    - to:
        - namespaceSelector:
            matchLabels:
              kubernetes.io/metadata.name: kube-system
      ports:
        - protocol: UDP
          port: 53
        - protocol: TCP
          port: 53
    {{- end }}
    {{- range .Values.networkPolicy.egress.additionalCIDRs }}
    - to:
        - ipBlock:
            cidr: {{ . | quote }}
    {{- end }}
    {{- if .Values.networkPolicy.egress.allowAll }}
    - {}
    {{- end }}
    {{- with .Values.networkPolicy.extraEgressRules }}
    {{- toYaml . | nindent 4 }}
    {{- end }}
{{- end }}
